[From: 王龙]
这个是什么，和我的想法有什么关系吗？：“/**
 * FepCognitiveCore.js (v2.0 流形动力学版 - Milestone 1)
 * 《燎原学社》NPC 神经计算流体力学引擎
 * 
 * [M1 升级核心]:
 * 1. 引入 this.ghosts (悬置隔离舱/纤维丛)，实现对极度悖论的 Epoché (悬置)，拒绝纯混合。
 * 2. 彻底废除 Modified Gram-Schmidt (MGS)，引入激活面等距旋转 (Isometric Bonnet Rotation)，
 *    实现了 100% 记忆无损的范式转移 (Paradigm Shift)。
 */

const EPAModule = require('./EPAModule'); 

class FepCognitiveCore {
    /**
     * @param {string} npcId - NPC 唯一标识
     * @param {ModelProvider} modelProvider - 注入模型抽象层
     * @param {Object} config - 引擎超参数
     */
    constructor(npcId, modelProvider, config = {}) {
        this.npcId = npcId;
        this.model = modelProvider;

        this.dim = this.model.getDimension();
        this.maxBasisDim = config.maxBasisDim || 16;

        // --- 1. 静态结构化先验 (认知基底) ---
        this.priorMean = new Float32Array(this.dim);
        this.W = []; 

        // --- 2. 连续隐状态与脉冲动力学 (NESS Dynamics) ---
        this.S_t = new Float32Array(this.dim);
        this.M_t = new Float32Array(this.dim);

        // 🌟 [M1 新增]：悬置隔离舱 (Suspended Ghosts)
        // 存放无法被解释、且能量极高，被系统判定为“悬置”的不确定性事件（几何极点）
        this.ghosts = []; 
        this.maxGhosts = config.maxGhosts || 5;

        // --- 3. FEP 评估指标与超参数 ---
        this.currentSurprise = 0.0;
        this.currentELBO = 1.0;
        this.gamma = config.gamma || 0.85;
        this.closureThreshold = config.closureThreshold || 0.3; // 普通破防阈值

        // 🌟 [M1 新增]：悬置阈值 (Epoché Threshold)
        // 超过此值，系统拒绝强制缝合，直接将残差打入冷宫
        this.suspensionThreshold = config.suspensionThreshold || (this.closureThreshold * 2.5); 

        this.epaMath = new EPAModule({ prepare: () => ({ all: () => [] }) }, { 
            dimension: this.dim, 
            maxBasisDim: this.maxBasisDim 
        });

        // [内存预分配] 针对高频 tick 的 Zero-Allocation 设计
        this._temp_S_centered = new Float32Array(this.dim);
        this._temp_S_projected = new Float32Array(this.dim);
        this._temp_dS_dt = new Float32Array(this.dim);
        this._temp_axis_activations = new Float32Array(this.maxBasisDim);
        // ============================================================================
        // 🌟 [M2 新增] 内生动力学事件总线与相变超参数
        // ============================================================================
        // 允许外部 Unity 传入回调函数，监听 NPC 的自发相变行为
        this.onInternalEvent = config.onInternalEvent || null;

        // 拓扑共振阈值：当游走的注意力 S_t 与悬置幽灵的余弦相似度 > 0.85 时引发顿悟
        this.epiphanyThreshold = config.epiphanyThreshold || 0.85; 

        // 认知过载积分器 (累积精神压力)
        this.dissonanceAccumulator = 0.0;                          
        this.dissonanceTolerance = config.dissonanceTolerance || 2.0; // 崩溃放弃阈值

        // 冷却计时器(秒)，防止高频 Tick 导致单帧连续刷屏触发
        this.cooldowns = { epiphany: 0, giveup: 0, proactive: 0 };
    }

    /**
     * [阶段 1：角色初始化与认知闭包]
     */
    async initPrior(lifeEvents) {
        console.log(`[FEP Core] 🧠 正在为 NPC [${this.npcId}] 烘焙初始先验...`);
        const vectors = [];
        const weights = [];
        let totalWeight = 0;

        for (const stage of lifeEvents) {
            for (const eventText of stage.events) {
                const vec = await this.model.getEmbedding({ text: eventText, mechanics: null });
                vectors.push(vec);
                weights.push(stage.weight);
                totalWeight += stage.weight;
            }
        }

        this.priorMean.fill(0);
        for (let i = 0; i < vectors.length; i++) {
            for (let d = 0; d < this.dim; d++) {
                this.priorMean[d] += vectors[i][d] * (weights[i] / totalWeight);
            }
        }

        this.epaMath.basisMean = this.priorMean;
        const clusterData = { vectors, weights, labels: weights.map((_, i) => `Mem_${i}`) };

        const svdResult = this.epaMath._computeWeightedPCA(clusterData);
        const K = this.epaMath._selectBasisDimension(svdResult.S);
        this.W = svdResult.U.slice(0, K);

        this.epaMath.orthoBasis = this.W; 
        this.epaMath.initialized = true;
        this.S_t.set(this.priorMean); 
        this.M_t.fill(0);
        this.ghosts = []; 

        console.log(`[FEP Core] ✅ 初始化完成！提取出 ${this.W.length} 根专属正交轴。`);
    }

    /**
     * ============================================================================
     * [阶段 2：马尔可夫毯观测]
     * 🌟 [M1 升级]：引入 UOT 悬置机制，将极端悖论分流至【悬置隔离舱】
     * ============================================================================
     */
    async observeEvent(ecsEvent) {
        if (!this.W || this.W.length === 0) return;

        const X_input = await this.model.getEmbedding({ text: ecsEvent.text, mechanics: ecsEvent.mechanics });
        const precision = ecsEvent.mechanics?.precision ?? 0.5; 
        const intensity = ecsEvent.mechanics?.intensity ?? 1.0; 

        // 1. 去质心化
        const X_prime = new Float32Array(this.dim);
        for (let i = 0; i < this.dim; i++) X_prime[i] = X_input[i] - this.priorMean[i];

        // 2. 正交投影
        const X_known = new Float32Array(this.dim);
        for (let k = 0; k < this.W.length; k++) {
            let dotProduct = 0.0;
            for (let i = 0; i < this.dim; i++) dotProduct += X_prime[i] * this.W[k][i];
            for (let i = 0; i < this.dim; i++) X_known[i] += dotProduct * this.W[k][i];
        }

        // 3. 残差解析
        const R_surprise = new Float32Array(this.dim);
        let surpriseEnergy = 0.0;
        let knownEnergy = 0.0;
        for (let i = 0; i < this.dim; i++) {
            R_surprise[i] = X_prime[i] - X_known[i];
            surpriseEnergy += R_surprise[i] * R_surprise[i];
            knownEnergy += X_known[i] * X_known[i];
        }

        const rawSurpriseMag = Math.sqrt(surpriseEnergy);
        const knownMag = Math.sqrt(knownEnergy);
        const effectiveSurprise = rawSurpriseMag * precision * intensity;

        let requiresEvolution = false;
        let status = "ASSIMILATED";

        // ============================================================================
        // 🌟 [M1 核心逻辑] 不平衡最优传输：三重认知路由
        // ============================================================================
        if (effectiveSurprise < this.closureThreshold) {
            // [境界 1] 盲区/舒适区：完全同化
            this.currentSurprise = 0.0;
            this.currentELBO = Math.min(1.0, this.currentELBO + 0.05); 
            const driftRate = 0.1 * precision;
            for (let i = 0; i < this.dim; i++) {
                this.S_t[i] += (X_known[i] - this.S_t[i]) * driftRate;
            }

        } else if (effectiveSurprise < this.suspensionThreshold) {
            // [境界 2] 认知失调 (可控破防)：压入 M_t 形成动力学脉冲
            status = "PUNCTURED";
            this.currentSurprise = effectiveSurprise;
            this.currentELBO = Math.max(0.1, this.currentELBO - (effectiveSurprise * 0.2)); 

            for (let i = 0; i < this.dim; i++) {
                this.M_t[i] += R_surprise[i] * precision * intensity;
            }

            if (effectiveSurprise > this.closureThreshold * 1.5) {
                requiresEvolution = true;
                this.pendingResidual = new Float32Array(R_surprise); 
                this.pendingRawInput = new Float32Array(X_input);
                this.pendingKnown = new Float32Array(X_known); // M1: 备份激活面，为旋转做准备
            }

        } else {
            // 🌟 [境界 3] 极境悬置 (Epoché)
            // 悖论太大！绝对不能压入 M_t 制造缝合怪。将其打入悬置隔离舱！
            status = "SUSPENDED";
            this.currentSurprise = effectiveSurprise;
            this.currentELBO = Math.max(0.01, this.currentELBO - (effectiveSurprise * 0.4)); // ELBO 暴跌表示极度怀疑

            const ghostVec = new Float32Array(this.dim);
            if (rawSurpriseMag > 1e-9) {
                for(let i=0; i<this.dim; i++) ghostVec[i] = R_surprise[i] / rawSurpriseMag;
            }

            this.ghosts.push({
                vector: ghostVec,
                energy: effectiveSurprise,
                rawInput: new Float32Array(X_input),
                known: new Float32Array(X_known),
                text: ecsEvent.text,
                age: 0
            });
            if (this.ghosts.length > this.maxGhosts) this.ghosts.shift(); // 遗忘最老的悬置

            // 给予主状态一个被物理截断的微小战栗，防止其毫无反应
            const cappedShock = this.closureThreshold * 1.5;
            for (let i = 0; i < this.dim; i++) {
                this.M_t[i] += ghostVec[i] * cappedShock;
            }

            console.warn(`[FEP Core] 👻 触发【认知悬置】！事件能量(${effectiveSurprise.toFixed(2)})撕裂流形，拒绝融合，已生成幽灵锚点隔离。`);
        }

        return {
            status, knownMagnitude: knownMag, surpriseMagnitude: rawSurpriseMag, 
            effectiveSurprise, elbo: this.currentELBO, requiresEvolution, activeGhosts: this.ghosts.length
        };
    }

    /**
     * [阶段 3：NESS 连续动力学演化]
     */
    tick(deltaTime) {
        if (!this.W || this.W.length === 0) return this._emptyTelemetry();

        // 🌟 [M1 新增] 幽灵舱(Ghosts) 的生命周期衰减
        // 悬置的悖论如果没有触发顿悟，会随着时间慢慢淡忘
        const ghostDecay = Math.exp(-0.1 * deltaTime); 
        for (let i = this.ghosts.length - 1; i >= 0; i--) {
            this.ghosts[i].age += deltaTime;
            this.ghosts[i].energy *= ghostDecay;
            if (this.ghosts[i].energy < 0.1) {
                this.ghosts.splice(i, 1); 
            }
        }

        const lambda = 2.0;               
        const alpha_homeostasis = 0.5;    
        const alpha_manifold = 3.5;       
        const beta_pulse = 1.0;           

        // 1. 脉冲衰减
        const decayFactor = Math.exp(-lambda * deltaTime);
        let currentPulseEnergy = 0.0;
        for (let i = 0; i < this.dim; i++) {
            this.M_t[i] *= decayFactor;
            currentPulseEnergy += this.M_t[i] * this.M_t[i];
        }
        const pulseMag = Math.sqrt(currentPulseEnergy);

        // 2. NESS 投影
        for (let i = 0; i < this.dim; i++) {
            this._temp_S_centered[i] = this.S_t[i] - this.priorMean[i];
            this._temp_S_projected[i] = 0.0;
        }
        this._temp_axis_activations.fill(0);
        for (let k = 0; k < this.W.length; k++) {
            let dot = 0.0;
            for (let i = 0; i < this.dim; i++) dot += this._temp_S_centered[i] * this.W[k][i];
            this._temp_axis_activations[k] = dot;
            for (let i = 0; i < this.dim; i++) this._temp_S_projected[i] += dot * this.W[k][i];
        }

        // 3. 欧拉积分
        let stateVelocitySq = 0.0;
        let dissonanceSq = 0.0;
        for (let i = 0; i < this.dim; i++) {
            const force_homeo = -alpha_homeostasis * this._temp_S_centered[i];
            const force_manifold = alpha_manifold * (this._temp_S_projected[i] - this._temp_S_centered[i]);
            const force_external = beta_pulse * this.M_t[i];

            this._temp_dS_dt[i] = force_homeo + force_manifold + force_external;
            this.S_t[i] += this._temp_dS_dt[i] * deltaTime;

            stateVelocitySq += this._temp_dS_dt[i] * this._temp_dS_dt[i];
            const diff = this._temp_S_projected[i] - this._temp_S_centered[i];
            dissonanceSq += diff * diff;
        }

        const stateVelocity = Math.sqrt(stateVelocitySq);
        const dissonanceMag = Math.sqrt(dissonanceSq);

        // 4. ELBO 恢复 
        // ============================================================================
        // 🌟 [M2 核心升级] 活体自驱动：内生动力学相变触发器 (Endogenous Phase Transitions)
        // ============================================================================

        // 0. 更新冷却时间
        if (this.cooldowns.epiphany > 0) this.cooldowns.epiphany -= deltaTime;
        if (this.cooldowns.giveup > 0) this.cooldowns.giveup -= deltaTime;
        if (this.cooldowns.proactive > 0) this.cooldowns.proactive -= deltaTime;

        // 1. 积分认知失调精神压力
        if (dissonanceMag > 0.1) {
            this.dissonanceAccumulator += dissonanceMag * deltaTime;
        } else {
            this.dissonanceAccumulator = Math.max(0, this.dissonanceAccumulator - deltaTime * 0.5); // 缓慢泄压
        }

        let emittedEvent = null;

        // 【触发器 A：内部顿悟 (EVENT_EPIPHANY)】 -> 拓扑共振检测
        // 物理图像：M_t 推动 S_t 游走，S_t 偶然闯入了悬置气泡的领地，发生几何对齐！
        if (this.ghosts.length > 0 && this.cooldowns.epiphany <= 0) {
            let sMagSq = 0.0;
            for (let i = 0; i < this.dim; i++) sMagSq += this._temp_S_centered[i] * this._temp_S_centered[i];
            const sMag = Math.sqrt(sMagSq);

            if (sMag > 1e-5) {
                // 倒序遍历，方便 splice 移除
                for (let i = this.ghosts.length - 1; i >= 0; i--) {
                    const ghost = this.ghosts[i];
                    let dot = 0.0;
                    for (let d = 0; d < this.dim; d++) {
                        dot += (this._temp_S_centered[d] / sMag) * ghost.vector[d];
                    }

                    // 💥 发生拓扑共振！潜意识的游走撞破了悬置的气泡！
                    if (dot > this.epiphanyThreshold) {
                        const resolvedGhost = this.ghosts.splice(i, 1)[0];

                        // 将 Ghost 实体化，提取回现实，作为下一次 Bonnet 等距旋转的原料
                        this.pendingResidual = new Float32Array(resolvedGhost.vector);
                        this.pendingRawInput = new Float32Array(resolvedGhost.rawInput);
                        this.pendingKnown = new Float32Array(resolvedGhost.known);

                        emittedEvent = "EVENT_EPIPHANY";
                        if (this.onInternalEvent) {
                            this.onInternalEvent(emittedEvent, {
                                reason: "注意力游走触发拓扑共振，解开历史悬置！",
                                ghostText: resolvedGhost.text,
                                resonance: dot
                            });
                        }
                        this.cooldowns.epiphany = 5.0; // 进入长冷却
                        break; // 一帧只触发一次
                    }
                }
            }
        }

        // 【触发器 B：内部悬置 / 放弃思考 (EVENT_SUSPEND_GIVEUP)】
        // 物理图像：失调压力突破阈值，流形无法闭合，大脑强制宕机保护
        if (!emittedEvent && this.dissonanceAccumulator > this.dissonanceTolerance && this.cooldowns.giveup <= 0) {
            emittedEvent = "EVENT_SUSPEND_GIVEUP";
            if (this.onInternalEvent) {
                this.onInternalEvent(emittedEvent, {
                    reason: "失调过载，NPC 大脑宕机自我保护，终止当前思考链。",
                    dissonance: dissonanceMag
                });
            }
            this.M_t.fill(0); // 放弃思考，强行清空冲击动能
            this.dissonanceAccumulator = 0;
            this.cooldowns.giveup = 8.0;
        }

        // 【触发器 C：主动试探驱动 (EVENT_PROACTIVE_DRIVE)】
        // 物理图像：动能已经平息，但内心有幽灵作祟导致自信度(ELBO)极低。迫切需要新信息。
        const isConverged = (pulseMag < 0.05 && stateVelocity < 0.05);
        if (!emittedEvent && isConverged && this.currentELBO < 0.35 && this.ghosts.length > 0 && this.cooldowns.proactive <= 0) {
            emittedEvent = "EVENT_PROACTIVE_DRIVE";
            if (this.onInternalEvent) {
                this.onInternalEvent(emittedEvent, {
                    reason: "系统陷入低自信收敛，求知欲(Epistemic)满载，迫使主动抢话试探。",
                    elbo: this.currentELBO
                });
            }
            this.cooldowns.proactive = 6.0;
            this.currentELBO += 0.2; // 略微回升，防止在同一帧无限死循环触发
        }

        // ------------------------------------------------------------------------
        // 5. 【输出全息引擎遥测数据】
        // ------------------------------------------------------------------------
        return {
            deltaTime: deltaTime,
            pulseEnergy: pulseMag, 
            cognitiveDissonance: dissonanceMag,
            thoughtVelocity: stateVelocity,
            confidenceELBO: this.currentELBO,
            dominantAxisIndex: this._getDominantAxisIndex(this._temp_axis_activations),
            activeGhosts: this.ghosts.length,
            emittedEvent: emittedEvent,  // 🌟 [M2 新增] 让 Unity 既可以回调，也可以轮询
            isConverged: isConverged
        };

    }

    _getDominantAxisIndex(activations) {
        let maxVal = -1; let maxIndex = 0;
        for (let i = 0; i < this.W.length; i++) {
            if (Math.abs(activations[i]) > maxVal) { maxVal = Math.abs(activations[i]); maxIndex = i; }
        }
        return maxIndex;
    }

    _emptyTelemetry() { return { pulseEnergy: 0, cognitiveDissonance: 0, thoughtVelocity: 0, confidenceELBO: 1.0, dominantAxisIndex: 0, activeGhosts: 0, isConverged: true }; }

    /**
     * [阶段 4：预期自由能 (EFE) 评估与最优事件合成]
     * (本阶段原样保留，它将在 M4 中被“潜变量前缀合成”彻底替换)
     */
    async computeEFEAction(candidateEvents = null) {
        if (!this.W || this.W.length === 0) return null;
        const pragmaticWeight = this.currentELBO;
        const epistemicWeight = 1.0 - this.currentELBO;
        const optimal_event_vector = new Float32Array(this.dim);
        const pragmatic_dir = new Float32Array(this.dim);

        for (let i = 0; i < this.dim; i++) this._temp_S_centered[i] = this.S_t[i] - this.priorMean[i];
        for (let k = 0; k < this.W.length; k++) {
            let dot = 0.0;
            for (let i = 0; i < this.dim; i++) dot += this._temp_S_centered[i] * this.W[k][i];
            for (let i = 0; i < this.dim; i++) pragmatic_dir[i] += dot * this.W[k][i];
        }

        const epistemic_dir = this.M_t;
        for (let i = 0; i < this.dim; i++) {
            optimal_event_vector[i] = this.priorMean[i] + (pragmaticWeight * pragmatic_dir[i]) + (epistemicWeight * epistemic_dir[i]);
        }

        if (!candidateEvents || candidateEvents.length === 0) {
            return { mode: "CONTINUOUS", optimalEventTensor: optimal_event_vector, elbo: this.currentELBO };
        }

        let bestEvent = null; let minEFE = Infinity; const evaluationReports = [];
        for (const event of candidateEvents) {
            const V_cand = await this.model.getEmbedding({ text: event.text, mechanics: event.mechanics });
            const V_centered = new Float32Array(this.dim);
            for (let i = 0; i < this.dim; i++) V_centered[i] = V_cand[i] - this.priorMean[i];

            let knownEnergy = 0.0, totalEnergy = 0.0;
            for (let k = 0; k < this.W.length; k++) {
                let dot = 0.0;
                for (let i = 0; i < this.dim; i++) dot += V_centered[i] * this.W[k][i];
                knownEnergy += dot * dot;
            }
            for (let i = 0; i < this.dim; i++) totalEnergy += V_centered[i] * V_centered[i];
            const risk = Math.max(0, totalEnergy - knownEnergy);

            let infoGain = 0.0;
            for (let i = 0; i < this.dim; i++) infoGain += V_centered[i] * this.M_t[i];
            infoGain = Math.max(0.0, infoGain);

            const efe = (pragmaticWeight * risk) - (epistemicWeight * infoGain);
            evaluationReports.push({ event, efe, risk, infoGain });
            if (efe < minEFE) { minEFE = efe; bestEvent = event; }
        }

        return { mode: "DISCRETE_EVALUATION", bestEvent, optimalEventTensor: optimal_event_vector, elbo: this.currentELBO, minEFE, reports: evaluationReports };
    }

    /**
     * ============================================================================
     * [阶段 5：记忆流形的无损重塑 (Prior Evolution)]
     * 🌟 [M1 核弹级更新]：彻底废除 MGS，引入“激活面等距旋转 (Activated-Plane Rotation)”
     * ============================================================================
     */
    evolvePrior(learningRate = 0.15) {
        if (!this.pendingResidu”
